public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    /**
     * Stages one NPSP Data Import record per gift, processes the batch synchronously
     * through NPSP's Data Import engine, and returns one ImportResult per gift in
     * input order.
     *
     * Relies on the org's Data Import settings (defaults: match contacts on
     * FirstName / LastName / Email; never match existing donations).
     *
     * @param gifts  up to 200 WebGift records; null or empty returns an empty list
     * @return       List&lt;ImportResult&gt; in the same order as the input
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        // Guard: null / empty
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // ── 1. Create the Data Import Batch ──────────────────────────────────
        NPE01__DataImportBatch__c batch = new NPE01__DataImportBatch__c();
        batch.NPE01__Name__c            = 'Web Gift Import ' + DateTime.now().getTime();
        batch.NPE01__Status__c          = 'New';
        batch.NPE01__DataImportType__c  = 'Contact_Opportunity';
        insert batch;

        // ── 2. Stage one Data Import record per gift ─────────────────────────
        List<NPE01__DataImport__c> importRows = new List<NPE01__DataImport__c>(gifts.size());
        for (WebGift gift : gifts) {
            NPE01__DataImport__c row = new NPE01__DataImport__c();
            row.NPE01__Batch__c          = batch.Id;
            row.NPE01__Status__c         = 'New';
            row.NPE01__DataImportType__c = 'Contact_Opportunity';
            row.NPE01__JSON__c           = buildImportJson(gift);
            importRows.add(row);
        }
        insert importRows;          // single DML – bulk-safe for up to 200 rows

        // ── 3. Process the batch synchronously via NPSP's Apex API ──────────
        //    The engine applies the org's Data Import settings:
        //      • contact matching on FirstName, LastName, Email
        //      • household auto-creation
        //      • donation processing (always creates a new Opportunity;
        //        never matches an existing donation)
        //    Individual row rejections are handled inside the engine;
        //    they do not abort the remaining rows.
        NPE01__DataImportProcess.process(batch.Id, true);   // true = synchronous / same tx

        // ── 4. Query back the processed rows and build results ──────────────
        Map<Id, NPE01__DataImport__c> processedMap =
            new Map<Id, NPE01__DataImport__c>(
                [SELECT Id,
                        NPE01__Status__c,
                        NPE01__Error__c,
                        NPE01__ContactId__c,
                        NPE01__OpportunityId__c
                 FROM NPE01__DataImport__c
                 WHERE NPE01__Batch__c = :batch.Id]
            );

        List<ImportResult> results = new List<ImportResult>(importRows.size());
        for (Integer i = 0; i < importRows.size(); i++) {
            ImportResult r = new ImportResult();
            NPE01__DataImport__c rec = processedMap.get(importRows[i].Id);

            if (rec != null) {
                r.success = 'Processed'.equals(rec.NPE01__Status__c);
                if (r.success) {
                    r.contactId     = rec.NPE01__ContactId__c;
                    r.opportunityId = rec.NPE01__OpportunityId__c;
                } else {
                    r.errorMessage = rec.NPE01__Error__c;
                }
            } else {
                // Should not happen, but guard against it
                r.success        = false;
                r.errorMessage   = 'Data Import record not found after processing.';
            }
            results.add(r);
        }

        return results;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Builds the JSON payload that NPSP's Data Import engine expects for a
    // Contact + Opportunity (donation) row.
    //
    // The engine reads:
    //   "Contact"     – fields used for matching / creation
    //   "Opportunity" – the donation to create (always new; existing
    //                   donations are never matched per the org setting)
    // ─────────────────────────────────────────────────────────────────────────
    private static String buildImportJson(WebGift gift) {

        // Contact – the three fields NPSP matches on by default
        Map<String, Object> contactFields = new Map<String, Object>();
        contactFields.put('FirstName', gift.firstName);
        contactFields.put('LastName',  gift.lastName);
        contactFields.put('Email',     gift.email);

        // Opportunity – the one-off gift / donation
        Map<String, Object> oppFields = new Map<String, Object>();
        oppFields.put('Name',      buildOpportunityName(gift));
        oppFields.put('Amount',    gift.amount);
        oppFields.put('CloseDate', gift.giftDate != null ? gift.giftDate.format('yyyy-MM-dd') : null);

        // Top-level envelope
        Map<String, Object> payload = new Map<String, Object>();
        payload.put('Contact',     contactFields);
        payload.put('Opportunity', oppFields);

        return JSON.serialize(payload);
    }

    private static String buildOpportunityName(WebGift gift) {
        String fn = (gift.firstName != null && gift.firstName.trim().hasLength())
                   ? gift.firstName.trim() : '';
        String ln = (gift.lastName  != null && gift.lastName.trim().hasLength())
                   ? gift.lastName.trim()  : '';
        String donorName = (fn + ' ' + ln).trim();
        return (donorName.hasLength() ? donorName : 'Website') + ' Gift';
    }
}
