public class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all GAU allocations on the given opportunity with one allocation per GAU/percent entry.
     * Percentages are stored on the allocation so that NPSP keeps the dollar amounts in sync
     * with the opportunity amount (e.g. a 60/40 split on $1,000 becomes $1,200/$800 at $2,000).
     *
     * @param opportunityId   The Opportunity Id.
     * @param percentByGauId  Keys = npsp__General_Accounting_Unit__c Ids; values = percent (60 = 60%).
     * @return The list of newly inserted npsp__Allocation__c records.
     * @throws AllocationException when input is invalid.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // --- Validation (no DML yet) ---

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must not be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' is null.');
            }
            if (pct <= 0) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Total percentages (' + totalPercent + ') exceed 100. Total must be 100 or less.');
        }

        // Verify every GAU exists and is active
        List<npsp__General_Accounting_Unit__c> gauList = [
            SELECT Id, npsp__Is_Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :percentByGauId.keySet()
        ];
        Map<Id, Boolean> activeMap = new Map<Id, Boolean>();
        for (npsp__General_Accounting_Unit__c gau : gauList) {
            activeMap.put(gau.Id, gau.npsp__Is_Active__c);
        }

        for (Id gauId : percentByGauId.keySet()) {
            if (!activeMap.containsKey(gauId) || !activeMap.get(gauId)) {
                throw new AllocationException('GAU ' + gauId + ' is inactive or does not exist.');
            }
        }

        // --- Mutate data (all validated) ---

        // Delete existing allocations for this opportunity
        List<npsp__Allocation__c> existingAllocs = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocs.isEmpty()) {
            Delete existingAllocs;
        }

        // Build and insert new allocations
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            npsp__Allocation__c alloc = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Allocated_Percent__c = percentByGauId.get(gauId)
            );
            newAllocations.add(alloc);
        }

        Insert newAllocations;

        return newAllocations;
    }
}
```

**How it satisfies each requirement:**

| Requirement | How it's met |
|---|---|
| Replace all existing allocations | Queries and `Delete`s every `npsp__Allocation__c` for the opportunity, then `Insert`s fresh ones. |
| Amounts stay correct when Opportunity Amount changes | Only `npsp__Allocated_Percent__c` is set. NPSP's `npsp__Amount__c` on Allocation is a formula (`Opportunity.Amount × percent / 100`), so any change to the opportunity amount automatically recalculates each allocation dollar value with no extra code. |
| Validate before mutating | All checks (null/empty map, null/≤0 percent, sum > 100, inactive GAU) happen **before** any `Delete` or `Insert`. |
| Throw `AllocationException` on bad input | Each validation failure throws the inner `AllocationException` with a descriptive message. |
| Total < 100 allowed | Only `> 100` is rejected; 80 % is fine. |
| Return inserted allocations | The method returns the `List<npsp__Allocation__c>` after the `Insert` (populated with Ids). |

