public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ── Collect unique IDs ──────────────────────────────────────────────
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ── SOQL 1: Opportunities ───────────────────────────────────────────
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // ── SOQL 2: OpportunityContactRoles ─────────────────────────────────
        List<OpportunityContactRole> allOPRs = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId IN :contactIds
        ];
        Map<String, OpportunityContactRole> oprMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole opr : allOPRs) {
            String key = opr.OpportunityId + '|' + opr.ContactId;
            oprMap.put(key, opr);
        }

        // ── SOQL 3: Existing Partial Soft Credits ───────────────────────────
        List<npsp__Partial_Soft_Credit__c> allPSCs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact_Role__c,
                   npsp__Amount__c, npsp__Role__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
        ];
        Map<String, npsp__Partial_Soft_Credit__c> pscMap =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : allPSCs) {
            String key = psc.npsp__Opportunity__c + '|' + psc.npsp__Contact_Role__c;
            pscMap.put(key, psc);
        }

        // ── Validation (no DML has occurred yet) ────────────────────────────
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + req.opportunityId);
            }

            // Primary-contact guard
            if (String.valueOf(opp.npsp__Primary_Contact__c) == String.valueOf(req.contactId)) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId + ' is the primary contact of opportunity '
                    + req.opportunityId);
            }

            // Amount guards
            if (req.amount == null) {
                throw new SoftCreditException(
                    'Amount is null for contact ' + req.contactId
                    + ' on opportunity ' + req.opportunityId);
            }
            if (req.amount <= 0) {
                throw new SoftCreditException(
                    'Amount must be positive for contact ' + req.contactId
                    + ' on opportunity ' + req.opportunityId);
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount ' + req.amount + ' exceeds opportunity amount ' + opp.Amount
                    + ' for opportunity ' + req.opportunityId);
            }
        }

        // ── Build OPR insert / update lists ─────────────────────────────────
        Map<String, OpportunityContactRole> oprByKey =
            new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> oprsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> oprsToUpdate = new List<OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;
            OpportunityContactRole opr = oprMap.get(key);

            if (opr != null) {
                // OPR exists – update role if it differs
                if (String.valueOf(opr.Role) != String.valueOf(req.role)) {
                    opr.Role = req.role;
                    oprsToUpdate.add(opr);
                }
                oprByKey.put(key, opr);
            } else {
                // OPR does not exist – create one
                opr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId     = req.contactId,
                    Role          = req.role
                );
                oprsToInsert.add(opr);
                oprByKey.put(key, opr);
            }
        }

        // ── DML 1: Insert new OPRs ──────────────────────────────────────────
        if (!oprsToInsert.isEmpty()) {
            insert oprsToInsert;
        }

        // ── DML 2: Update existing OPRs ─────────────────────────────────────
        if (!oprsToUpdate.isEmpty()) {
            update oprsToUpdate;
        }

        // ── Build PSC insert / update lists ─────────────────────────────────
        // After the insert above, every OPR in oprByKey has a populated Id.
        List<npsp__Partial_Soft_Credit__c> pscsToInsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;
            OpportunityContactRole opr = oprByKey.get(key);

            String pscKey = req.opportunityId + '|' + opr.Id;
            npsp__Partial_Soft_Credit__c existingPsc = pscMap.get(pscKey);

            if (existingPsc != null) {
                existingPsc.npsp__Amount__c = req.amount;
                existingPsc.npsp__Role__c   = req.role;
                pscsToUpdate.add(existingPsc);
            } else {
                pscsToInsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c  = req.opportunityId,
                    npsp__Contact_Role__c = opr.Id,
                    npsp__Amount__c       = req.amount,
                    npsp__Role__c         = req.role
                ));
            }
        }

        // ── DML 3: Insert new PSCs ──────────────────────────────────────────
        if (!pscsToInsert.isEmpty()) {
            insert pscsToInsert;
        }

        // ── DML 4: Update existing PSCs ─────────────────────────────────────
        if (!pscsToUpdate.isEmpty()) {
            update pscsToUpdate;
        }
    }
}
```

**Summary of resource usage (200-request call):**

| Resource | Count | Limit |
|----------|-------|-------|
| SOQL queries | 3 (Opportunities, OPRs, PSCs) | 4 |
| DML statements | 4 (insert OPRs, update OPRs, insert PSCs, update PSCs) | 4 |

Each DML is guarded by an `isEmpty()` check so no no-op DML statements are issued. All validation completes before any DML, guaranteeing atomicity of the "all-or-nothing" contract.

