```apex
public class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        // Validate numberOfPayments before any DML
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be greater than zero.');
        }

        // Validate the opportunity is open
        Opportunity opp = [SELECT Id, Amount, IsClosed FROM Opportunity WHERE Id = :opportunityId];
        if (opp.IsClosed) {
            throw new PaymentPlanException('Cannot schedule installments on a closed opportunity.');
        }

        // Query all existing payments for this opportunity
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Amount__c, npe01__IsPaid__c, npe01__WrittenOff__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        Decimal paidTotal = 0;
        Decimal writtenOffTotal = 0;
        List<Id> deletableIds = new List<Id>();

        for (npe01__OppPayment__c p : existingPayments) {
            if (p.npe01__IsPaid__c) {
                paidTotal += p.npe01__Amount__c;
            } else if (p.npe01__WrittenOff__c) {
                writtenOffTotal += p.npe01__Amount__c;
            } else {
                // Unpaid and not written off — candidate for deletion
                deletableIds.add(p.Id);
            }
        }

        // Outstanding = Opportunity amount − paid − written-off
        Decimal outstanding = opp.Amount - paidTotal - writtenOffTotal;

        if (outstanding <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero.');
        }

        // Base amount per payment, rounded down to the cent
        Decimal baseAmount = (outstanding / numberOfPayments).setScale(2, RoundingMode.DOWN);

        // Build the new payments
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount;
            if (i == numberOfPayments - 1) {
                // Last payment absorbs any rounding remainder
                amount = outstanding - (baseAmount * (numberOfPayments - 1));
            } else {
                amount = baseAmount;
            }

            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c  = opportunityId,
                npe01__Amount__c       = amount,
                npe01__PaymentDate__c  = firstPaymentDate.addMonths(i),
                npe01__IsPaid__c       = false,
                npe01__WrittenOff__c   = false,
                npe01__PaymentStatus__c = 'Unpaid',
                npe01__Installment__c  = i + 1
            ));
        }

        // Delete the old unpaid / not-written-off payments
        if (!deletableIds.isEmpty()) {
            Delete deletableIds;
        }

        // Insert the new installment plan
        Insert newPayments;

        return newPayments;
    }
}
```

