public class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // Validate amount
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be a positive, non-null value.');
        }

        // Look up the contact
        Contact contact = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contact == null) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        // Validate household association
        if (contact.AccountId == null) {
            throw new IllegalArgumentException('Contact is not associated with a household account.');
        }

        Id householdAccountId = contact.AccountId;

        // Retrieve other household members (everyone except the primary donor)
        List<Contact> otherMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdAccountId
            AND Id != :contact.Id
        ];

        // Look up the NPSP Contact Role records
        ContactRole donorRole = [SELECT Id FROM ContactRole WHERE Name = 'Donor' LIMIT 1];
        ContactRole hhMemberRole = [SELECT Id FROM ContactRole WHERE Name = 'Household Member' LIMIT 1];

        // Build the Opportunity
        String oppName = contact.FirstName + ' ' + contact.LastName + ' Donation ' + String.valueOf(giftDate);

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = householdAccountId,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            npe01__IsDonation__c = true
        );

        insert opp;

        // Build Contact Roles
        List<OpportunityContactRole> ocrs = new List<OpportunityContactRole>();

        // Primary contact – Donor role with full allocation
        ocrs.add(new OpportunityContactRole(
            OpportunityId = opp.Id,
            ContactId = contact.Id,
            ContactRole = donorRole.Id,
            IsPrimary = true,
            npe01__Donor_Allocation__c = amount
        ));

        // All other household members – Household Member role
        for (Contact member : otherMembers) {
            ocrs.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId = member.Id,
                ContactRole = hhMemberRole.Id,
                IsPrimary = false,
                npe01__Donor_Allocation__c = 0
            ));
        }

        insert ocrs;

        // Create exactly one Payment – Paid, full amount, dated giftDate
        npe01__Payment__c payment = new npe01__Payment__c(
            npe01__OppRecord__c = opp.Id,
            npe01__Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Status__c = 'Paid'
        );

        insert payment;

        return opp.Id;
    }
}
