public class OPP_MajorGiftFollowUp_TDTM extends TrgrHandler {

    public override Boolean isSynchronous() {
        return true;
    }

    public override void Execute() {
        List<Task> tasksToCreate = new List<Task>();

        if (Trigger.isInsert) {
            for (Opportunity opp : (List<Opportunity>) Trigger.new) {
                if (isQualified(opp)) {
                    tasksToCreate.add(buildTask(opp));
                }
            }
        }

        if (Trigger.isUpdate) {
            for (Opportunity opp : (List<Opportunity>) Trigger.new) {
                Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
                if (isQualified(opp) && !isQualified(oldOpp)) {
                    tasksToCreate.add(buildTask(opp));
                }
            }
        }

        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }
    }

    private static Boolean isQualified(Opportunity opp) {
        return opp.StageName == 'Closed Won'
            && opp.Amount != null
            && opp.Amount >= 5000;
    }

    private static Task buildTask(Opportunity opp) {
        return new Task(
            Subject      = 'Major gift thank-you call',
            Priority     = 'High',
            Status       = 'Not Started',
            WhatId       = opp.Id,
            WhoId        = opp.npsp__Primary_Contact__c,
            OwnerId      = opp.OwnerId,
            ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
        );
    }
}
