public class TA_Opportunity_CollectForErpSync extends Trigger_Action__e {

    private static Set<Id> idsToSync;

    /**
     * Returns a defensive copy of the Ids collected for this DML operation.
     */
    public static Set<Id> getIdsToSync() {
        return idsToSync == null ? new Set<Id>() : new Set<Id>(idsToSync);
    }

    /**
     * Clears the collected Ids. Called by the finalizer after it has enqueued
     * (or decided not to enqueue) the job, so the next DML operation starts fresh.
     */
    public static void clearIdsToSync() {
        idsToSync = null;
    }

    public override void action() {
        if (idsToSync == null) {
            idsToSync = new Set<Id>();
        }

        if (Trigger.isInsert) {
            for (Opportunity opp : (List<Opportunity>) Trigger.new) {
                idsToSync.add(opp.Id);
            }
        }
        else if (Trigger.isUpdate) {
            for (Id id : Trigger.newMap.keySet()) {
                Opportunity newOpp = (Opportunity) Trigger.newMap.get(id);
                Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(id);
                if (newOpp.StageName != oldOpp.StageName) {
                    idsToSync.add(id);
                }
            }
        }
    }
}
