public class OpportunityErpSyncFinalizer extends DML_Finalizer__e {

    public override void finalize() {
        Set<Id> ids = TA_Opportunity_CollectForErpSync.getIdsToSync();

        if (!ids.isEmpty()) {
            System.enqueueQueueable(new OpportunityErpSyncJob(ids));
        }

        // Always clear so the next DML operation (even on a different sObject)
