public class TA_Contact_PreventDuplicateEmail implements TAF_Trigger_Action_Interface {

    private static final String DUPLICATE_EMAIL_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void execute(Map<Id, SObject> triggers, Trigger_Action__mdt triggerAction) {
        if (Trigger.isBefore && Trigger.isInsert) {
            handleBeforeInsert(triggers);
        } else if (Trigger.isBefore && Trigger.isUpdate) {
            handleBeforeUpdate(triggers);
        }
    }

    // ─────────────────────────── Before Insert ───────────────────────────

    private void handleBeforeInsert(Map<Id, SObject> triggers) {
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (SObject sObj : triggers.values()) {
            Contact c = (Contact) sObj;
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                toCheck.add(c);
                accountIds.add(c.AccountId);
            }
        }

        if (toCheck.isEmpty()) {
            return;
        }

        Map<String, Set<Id>> dbMap = buildExistingMap(accountIds);
        Set<String> claimed = new Set<String>();

        for (Contact c : toCheck) {
            String key = buildKey(c.AccountId, c.Email);
            if (dbMap.containsKey(key) || claimed.contains(key)) {
                c.addError(DUPLICATE_EMAIL_MESSAGE);
            } else {
                claimed.add(key);
            }
        }
    }

    // ─────────────────────────── Before Update ───────────────────────────

    private void handleBeforeUpdate(Map<Id, SObject> triggers) {
        Map<Id, Contact> oldMap = new Map<Id, Contact>();
        for (Contact oldC : (List<Contact>) Trigger.old) {
            oldMap.put(oldC.Id, oldC);
        }

        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (Id id : triggers.keySet()) {
            Contact newC = (Contact) triggers.get(id);
            Contact oldC = oldMap.get(id);

            // Skip contacts without an account or without an email
            if (newC.AccountId == null || String.isBlank(newC.Email)) {
                continue;
            }

            // Only check contacts whose Email or AccountId actually changed
            Boolean emailChanged   = (oldC.Email     != newC.Email);
            Boolean accountChanged = (oldC.AccountId != newC.AccountId);

            if (emailChanged || accountChanged) {
                toCheck.add(newC);
                accountIds.add(newC.AccountId);
            }
        }

        if (toCheck.isEmpty()) {
            return;
        }

        Map<String, Set<Id>> dbMap = buildExistingMap(accountIds);

        // A contact never conflicts with itself – remove self-references
        for (Contact c : toCheck) {
            String key = buildKey(c.AccountId, c.Email);
            if (dbMap.containsKey(key)) {
                dbMap.get(key).remove(c.Id);
            }
        }

        Set<String> claimed = new Set<String>();

        for (Contact c : toCheck) {
            String key = buildKey(c.AccountId, c.Email);
            if ((dbMap.containsKey(key) && !dbMap.get(key).isEmpty())
                || claimed.contains(key)) {
                c.addError(DUPLICATE_EMAIL_MESSAGE);
            } else {
                claimed.add(key);
            }
        }
    }

    // ─────────────────────────── Shared helpers ───────────────────────────

    /**
     * Single SOQL query: fetch every Contact on the given accounts,
     * then build an in-memory map keyed by (accountId | UPPER(email)).
     */
    private Map<String, Set<Id>> buildExistingMap(Set<Id> accountIds) {
        Map<String, Set<Id>> result = new Map<String, Set<Id>>();
        if (accountIds.isEmpty()) {
            return result;
        }

        List<Contact> existing =
            [SELECT Id, AccountId, Email
             FROM Contact
             WHERE AccountId IN :accountIds];

        for (Contact c : existing) {
            if (c.Email != null && String.isNotBlank(c.Email)) {
                String key = buildKey(c.AccountId, c.Email);
                if (!result.containsKey(key)) {
                    result.put(key, new Set<Id>());
                }
                result.get(key).add(c.Id);
            }
        }

        return result;
    }

    private String buildKey(Id accountId, String email) {
        return accountId + '|' + String.upperCase(email);
    }
}
