public class TA_Lead_NormalizeContactInfo implements Trigger_Action__i {

    public virtual void handle(Map<String, Object> context) {
        if (Boolean.TRUE.equals((Boolean) context.get('Trigger.isBefore'))
         && Boolean.TRUE.equals((Boolean) context.get('Trigger.isInsert'))) {

            List<Lead> newLeads = (List<Lead>) context.get('Trigger.new');

            for (Lead lead : newLeads) {
                if (lead.Email != null) {
                    lead.Email = lead.Email.trim().toLowerCase();
                }
                if (lead.Company != null) {
                    lead.Company = lead.Company.trim();
                }
                if (String.isBlank(lead.LeadSource)) {
                    lead.LeadSource = 'Web';
                }
            }
        }
    }
}
