public class TA_Case_RollupOpenCount {

    public static void handle() {
        if (Trigger.isAfter) {
            if (Trigger.isInsert) {
                handleAfterInsert();
            } else if (Trigger.isUpdate) {
                handleAfterUpdate();
            } else if (Trigger.isDelete) {
                handleAfterDelete();
            } else if (Trigger.isUndelete) {
                handleAfterUndelete();
            }
        }
    }

    /**
     * After Insert: increment the count for each open case that has an Account.
     * Closed cases on insert do not change the count (it was 0 before).
     */
    private static void handleAfterInsert() {
        Map<Id, Integer> increments = new Map<Id, Integer>();

        for (Case c : Trigger.new) {
            if (c.AccountId != null && !c.IsClosed) {
                increments.put(c.AccountId, increments.getOrDefault(c.AccountId, 0) + 1);
            }
        }

        if (increments.isEmpty()) {
            return;
        }

        applyAdjustments(increments);
    }

    /**
     * After Update: handle IsClosed transitions and AccountId (lookup) changes.
     * - Open → Closed: decrement
     * - Closed → Open: increment
     * - Moved to new account: decrement old (if was open), increment new (if is open)
     */
    private static void handleAfterUpdate() {
        Map<Id, Integer> adjustments = new Map<Id, Integer>();

        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Case newCase = Trigger.new[i];
            Case oldCase = Trigger.old[i];

            if (newCase.AccountId != oldCase.AccountId) {
                // Lookup changed
                if (oldCase.AccountId != null && !oldCase.IsClosed) {
                    adjustments.put(oldCase.AccountId, adjustments.getOrDefault(oldCase.AccountId, 0) - 1);
                }
                if (newCase.AccountId != null && !newCase.IsClosed) {
                    adjustments.put(newCase.AccountId, adjustments.getOrDefault(newCase.AccountId, 0) + 1);
                }
            } else if (newCase.AccountId != null) {
                // Same account – check status transition
                if (!oldCase.IsClosed && newCase.IsClosed) {
                    adjustments.put(newCase.AccountId, adjustments.getOrDefault(newCase.AccountId, 0) - 1);
                } else if (oldCase.IsClosed && !newCase.IsClosed) {
                    adjustments.put(newCase.AccountId, adjustments.getOrDefault(newCase.AccountId, 0) + 1);
                }
            }
        }

        // Remove net-zero adjustments
        List<Id> zeroKeys = new List<Id>();
        for (Id id : adjustments.keySet()) {
            if (adjustments.get(id) == 0) {
                zeroKeys.add(id);
            }
        }
        for (Id id : zeroKeys) {
            adjustments.remove(id);
        }

        if (adjustments.isEmpty()) {
            return;
        }

        applyAdjustments(adjustments);
    }

    /**
     * After Delete: decrement the count for each open case being removed.
     * Uses Trigger.old because Trigger.new is empty in after-delete.
     */
    private static void handleAfterDelete() {
        Map<Id, Integer> decrements = new Map<Id, Integer>();

        for (Case c : Trigger.old) {
            if (c.AccountId != null && !c.IsClosed) {
                decrements.put(c.AccountId, decrements.getOrDefault(c.AccountId, 0) + 1);
            }
        }

        if (decrements.isEmpty()) {
            return;
        }

        // Negate to turn into decrements
        Map<Id, Integer> adjustments = new Map<Id, Integer>();
        for (Id id : decrements.keySet()) {
            adjustments.put(id, -decrements.get(id));
        }

        applyAdjustments(adjustments);
    }

    /**
     * After Undelete: increment the count for each open case being restored.
     * In after-undelete, Trigger.new holds the restored records.
     */
    private static void handleAfterUndelete() {
        Map<Id, Integer> increments = new Map<Id, Integer>();

        for (Case c : Trigger.new) {
            if (c.AccountId != null && !c.IsClosed) {
                increments.put(c.AccountId, increments.getOrDefault(c.AccountId, 0) + 1);
            }
        }

        if (increments.isEmpty()) {
            return;
        }

        applyAdjustments(increments);
    }

    /**
     * Single SOQL + single DML: query the affected accounts, apply the integer
     * adjustment, and update them. Null counts are treated as 0; results are
     * floored at 0 to guard against negative drift.
     */
    private static void applyAdjustments(Map<Id, Integer> adjustments) {
        List<Account> toUpdate = new List<Account>(
            [SELECT Id, FB_Open_Case_Count__c FROM Account WHERE Id IN :adjustments.keySet()]
        );

        Map<Id, Account> accountMap = new Map<Id, Account>(toUpdate);

        List<Account> accountsToUpdate = new List<Account>();

        for (Id accountId : adjustments.keySet()) {
            Account acc = accountMap.get(accountId);
            if (acc == null) {
                continue;
            }
            Integer current = acc.FB_Open_Case_Count__c == null ? 0 : acc.FB_Open_Case_Count__c.intValue();
            Integer newVal = current + adjustments.get(accountId);
            if (newVal < 0) {
                newVal = 0;
            }
            acc.FB_Open_Case_Count__c = newVal;
            accountsToUpdate.add(acc);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
