public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    /**
     * Tracks Opportunity Ids that already received an "Amount changed" Task
     * in the current transaction.  Because TA_Opportunity_RoundAmount (Order 20)
     * re-updates the same records, the trigger fires a second time; this static
     * set (persistent for the duration of the transaction) guarantees at most
     * one Task per Opportunity.
     */
    private static final Set<Id> _loggedOppIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasks = new List<Task>();

        for (Opportunity opp : triggerNew) {
            Opportunity oldOpp = oldMap.get(opp.Id);

            // Amount must have actually changed AND this opp must not already
            // have been logged in this transaction (guards against the
            // re-trigger caused by the rounding action).
            if (opp.Amount != oldOpp.Amount && !_loggedOppIds.contains(opp.Id)) {
                _loggedOppIds.add(opp.Id);
                tasks.add(new Task(
                    Subject  = 'Amount changed',
                    WhatId   = opp.Id,
                    Status   = 'Completed'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
